parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "thread_ts",
    "requests",
    "non_requests"
  ],
  "properties": {
    "thread_ts": {
      "type": "string",
      "pattern": "^\\d{10}\\.\\d{6}$"
    },
    "requests": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "request_ref",
          "source_message_ts",
          "requester",
          "for_user",
          "resource",
          "environment",
          "access_level",
          "justification",
          "duration",
          "status",
          "missing_fields",
          "clarifying_question",
          "flags"
        ],
        "properties": {
          "request_ref": {
            "description": "<ts of the message where the request first appears>#<1-based order in that message>",
            "type": "string",
            "pattern": "^\\d{10}\\.\\d{6}#\\d+$"
          },
          "source_message_ts": {
            "description": "All messages (incl. thread replies) this request was assembled from",
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string",
              "pattern": "^\\d{10}\\.\\d{6}$"
            }
          },
          "requester": {
            "description": "Slack user ID of the author",
            "type": "string",
            "pattern": "^[UW][A-Z0-9]+$"
          },
          "for_user": {
            "description": "Who needs the access: Slack user ID, email or name as written; null = same as requester",
            "type": [
              "string",
              "null"
            ],
            "maxLength": 200
          },
          "resource": {
            "description": "System / service / repo / DB the access is for, as named in the message",
            "type": [
              "string",
              "null"
            ],
            "maxLength": 200
          },
          "environment": {
            "type": [
              "string",
              "null"
            ],
            "enum": [
              "prod",
              "staging",
              "dev",
              "other",
              null
            ]
          },
          "access_level": {
            "type": [
              "string",
              "null"
            ],
            "enum": [
              "read",
              "write",
              "admin",
              null
            ]
          },
          "justification": {
            "type": [
              "string",
              "null"
            ],
            "maxLength": 500
          },
          "duration": {
            "description": "ISO 8601 duration (P7D, PT8H) or \"permanent\"",
            "type": [
              "string",
              "null"
            ],
            "pattern": "^(P(?=\\d|T\\d)(\\d+Y)?(\\d+M)?(\\d+W)?(\\d+D)?(T(\\d+H)?(\\d+M)?)?|permanent)$"
          },
          "status": {
            "type": "string",
            "enum": [
              "complete",
              "incomplete"
            ]
          },
          "missing_fields": {
            "type": "array",
            "uniqueItems": true,
            "items": {
              "type": "string",
              "enum": [
                "resource",
                "environment",
                "access_level",
                "justification",
                "duration"
              ]
            }
          },
          "clarifying_question": {
            "description": "Exactly one question to the author when status=incomplete, else null",
            "type": [
              "string",
              "null"
            ],
            "maxLength": 300
          },
          "flags": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "prompt_injection",
              "sensitive_data",
              "urgent_or_pressure",
              "ambiguous"
            ],
            "properties": {
              "prompt_injection": {
                "type": "boolean"
              },
              "sensitive_data": {
                "type": "boolean"
              },
              "urgent_or_pressure": {
                "type": "boolean"
              },
              "ambiguous": {
                "type": "boolean"
              }
            }
          }
        }
      }
    },
    "non_requests": {
      "description": "New messages that contain no request at all",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "message_ts",
          "reason"
        ],
        "properties": {
          "message_ts": {
            "type": "string",
            "pattern": "^\\d{10}\\.\\d{6}$"
          },
          "reason": {
            "type": "string",
            "maxLength": 200
          }
        }
      }
    }
  }
}

