parameters.jsCode:
// Mode: Run Once for Each Item. Sits between Get requester (after AI Agent) and Switch.
// Turn the AI Agent output into rows for access_requests / non_requests.
// The rows are saved after the Slack message in each branch, together with the decision.
// IDs, author and thread come from the Slack event (trusted), not from the LLM:
// the agent does not see message ts, so whatever ts it returns is made up.
// Status, risk and route are recomputed with the same rules as n8n/code/route.js.
const REQUIRED = ['resource', 'environment', 'access_level', 'justification', 'duration'];
const MAX_STANDARD_DAYS = 30;
const SENSITIVE_RESOURCE = /(vault|secret|kms|iam|root|billing|payment|pci|finance|payroll|hr\b|customer|pii|backup|prod[-_ ]?db)/i;

const durationDays = (d) => {
  if (!d || d === 'permanent') return Infinity;
  const m = d.match(/^P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?)?$/);
  if (!m) return Infinity;
  const [, y = 0, mo = 0, w = 0, dd = 0, h = 0, mi = 0] = m.map((x) => Number(x || 0));
  return y * 365 + mo * 30 + w * 7 + dd + h / 24 + mi / 1440;
};
const userId = (u) => (u || '').replace(/^<@([A-Z0-9]+)(\|[^>]*)?>$/, '$1');

const slack = $('Slack Trigger').item.json;
const agent = $('AI Agent').item.json;
const out = agent.output || { requests: [], non_requests: [] };
// Slack users.info from "Get requester" (empty if the lookup failed, e.g. no users:read scope).
const who = $json.id === slack.user ? $json : {};
const requesterName = who.profile?.real_name || who.real_name || who.profile?.display_name || who.name || null;
const requesterEmail = who.profile?.email || null;
const channel = slack.channel;
const ts = slack.ts;
const threadTs = slack.thread_ts || slack.ts;

const requests = (out.requests || []).map((r, i) => {
  const missing = REQUIRED.filter((f) => r[f] === null || r[f] === undefined || r[f] === '');
  const status = missing.length ? 'incomplete' : 'complete';
  const forUser = r.for_user && userId(r.for_user) !== slack.user ? r.for_user : null;
  const flags = {
    prompt_injection: !!r.flags?.prompt_injection,
    sensitive_data: !!r.flags?.sensitive_data,
    urgent_or_pressure: !!r.flags?.urgent_or_pressure,
    ambiguous: !!r.flags?.ambiguous,
  };

  const reasons = [];
  if (r.environment === 'prod') reasons.push('prod_environment');
  if (r.access_level === 'admin') reasons.push('admin_access');
  if (r.duration === 'permanent') reasons.push('permanent_access');
  else if (r.duration && durationDays(r.duration) > MAX_STANDARD_DAYS) reasons.push(`longer_than_${MAX_STANDARD_DAYS}d`);
  if (forUser) reasons.push('on_behalf_of_other_user');
  if (r.resource && SENSITIVE_RESOURCE.test(r.resource)) reasons.push('sensitive_resource');
  if (flags.prompt_injection) reasons.push('prompt_injection');
  if (flags.sensitive_data) reasons.push('secret_in_message');
  if (flags.urgent_or_pressure) reasons.push('pressure_to_bypass_process');
  if (flags.ambiguous) reasons.push('ambiguous');

  const high =
    reasons.some((x) => ['prompt_injection', 'secret_in_message', 'pressure_to_bypass_process'].includes(x)) ||
    (r.environment === 'prod' && (r.access_level === 'admin' || r.duration === 'permanent'));

  let route;
  if (flags.prompt_injection) route = 'devops_review';
  else if (status === 'incomplete') route = 'needs_clarification';
  else if (reasons.length) route = 'devops_review';
  else route = 'standard_approval';

  return {
    // Keyed by thread: a reply in the thread updates the same request instead of creating a new one.
    request_ref: `${threadTs}#${i + 1}`,
    channel,
    thread_ts: threadTs,
    source_message_ts: [ts],
    requester: slack.user,
    requester_name: requesterName,
    requester_email: requesterEmail,
    for_user: forUser,
    resource: r.resource ?? null,
    environment: r.environment ?? null,
    access_level: r.access_level ?? null,
    justification: r.justification ?? null,
    duration: r.duration ?? null,
    status,
    missing_fields: missing,
    clarifying_question: status === 'incomplete' ? r.clarifying_question ?? null : null,
    flags,
    redacted: false,
    is_risky: reasons.length > 0,
    risk_level: high ? 'high' : reasons.length ? 'medium' : 'low',
    risk_reasons: reasons,
    route,
    model: 'n8n AI Agent',
  };
});

// The whole Slack message is either part of a request or a non-request.
const non_requests = requests.length
  ? []
  : [{ channel, thread_ts: threadTs, message_ts: ts, reason: out.non_requests?.[0]?.reason ?? 'not an access request' }];

// One route for the whole message, so the Switch sees every request, not only the first one.
const anyRoute = (r) => requests.some((x) => x.route === r);
const messageRoute = !requests.length ? null
  : requests.some((x) => x.flags.prompt_injection) ? 'devops_review'
  : anyRoute('needs_clarification') ? 'needs_clarification'
  : anyRoute('devops_review') ? 'devops_review'
  : 'standard_approval';
// All questions of incomplete requests in one bot message.
const clarifyingText = requests.map((x) => x.clarifying_question).filter(Boolean).join('\n');
// What the approver in #validate needs to see.
const riskSummary = requests
  .map((x) => `• ${x.resource ?? '?'} — ${x.environment ?? '?'}, ${x.access_level ?? '?'}, ${x.duration ?? '?'}: ризик ${x.risk_level}` +
    (x.risk_reasons.length ? ` (${x.risk_reasons.join(', ')})` : ''))
  .join('\n');

// Keep the agent output: the Slack nodes after this one may still read $json.output.
return { json: { ...agent, requests, non_requests, route: messageRoute, clarifying_text: clarifyingText, risk_summary: riskSummary } };
